with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , EDU_CESS_TAX as CESS_AMOUNT
        , cast(null as varchar) as CGST_AMOUNT
        , cast(null as varchar) as SGST_AMOUNT
        , cast(null as varchar) as IGST_AMOUNT
        , cast(null as varchar) as STAMP_DUTY_AMOUNT
        , 'BJAZ_ENROLL_SCR_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_scr_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as CESS_AMOUNT
        , CGST_AMT as CGST_AMOUNT
        , SGST_AMT as SGST_AMOUNT
        , IGST_AMT as IGST_AMOUNT
        , STAMP_DUTY as STAMP_DUTY_AMOUNT
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as CESS_AMOUNT
        , CGST_AMT as CGST_AMOUNT
        , SGST_AMT as SGST_AMOUNT
        , IGST_AMT as IGST_AMOUNT
        , STAMP_DUTY_AMT as STAMP_DUTY_AMOUNT
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then CESS_AMOUNT end) as CESS_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then CGST_AMOUNT end) as CGST_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SGST_AMOUNT end) as SGST_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then IGST_AMOUNT end) as IGST_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then STAMP_DUTY_AMOUNT end) as STAMP_DUTY_AMOUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when CESS_AMOUNT is not null or CGST_AMOUNT is not null or SGST_AMOUNT is not null or IGST_AMOUNT is not null or STAMP_DUTY_AMOUNT is not null
                     then md5(upper(coalesce(cast(CESS_AMOUNT as varchar), '') || '|' || coalesce(cast(CGST_AMOUNT as varchar), '') || '|' || coalesce(cast(SGST_AMOUNT as varchar), '') || '|' || coalesce(cast(IGST_AMOUNT as varchar), '') || '|' || coalesce(cast(STAMP_DUTY_AMOUNT as varchar), '')))
                end as SAT_POLICY_TAX_BREAKUP_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_TAX_BREAKUP_HASHDIFF is not null
